BEGIN IMMEDIATE;
CREATE TABLE meta(key TEXT PRIMARY KEY,value INTEGER NOT NULL);
INSERT INTO meta VALUES('revision',1);
CREATE TABLE accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,provider TEXT NOT NULL);
CREATE TABLE conversations(account TEXT NOT NULL,id TEXT NOT NULL,subject TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(account,id),FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE messages(rowid INTEGER PRIMARY KEY,account TEXT NOT NULL,id TEXT NOT NULL,conversation_id TEXT NOT NULL,remote_id TEXT NOT NULL,sender_name TEXT NOT NULL,sender_email TEXT NOT NULL,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,sent_at TEXT NOT NULL,unread INTEGER NOT NULL,starred INTEGER NOT NULL,inbox INTEGER NOT NULL,sent INTEGER NOT NULL,source_hash TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(account,id),UNIQUE(account,remote_id),FOREIGN KEY(account,conversation_id) REFERENCES conversations(account,id));
CREATE INDEX messages_conversation ON messages(account,conversation_id,sent_at,id);
CREATE INDEX messages_order ON messages(account,sent_at DESC,id);
CREATE VIRTUAL TABLE message_fts USING fts5(sender,subject,body,tokenize='unicode61 remove_diacritics 2',prefix='2 3 4');
CREATE TABLE categories(account TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,PRIMARY KEY(account,id),FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE message_categories(account TEXT NOT NULL,message_id TEXT NOT NULL,category_id TEXT NOT NULL,PRIMARY KEY(account,message_id,category_id),FOREIGN KEY(account,message_id) REFERENCES messages(account,id),FOREIGN KEY(account,category_id) REFERENCES categories(account,id));
CREATE TABLE attachments(account TEXT NOT NULL,id TEXT NOT NULL,message_id TEXT NOT NULL,name TEXT NOT NULL,mime_type TEXT NOT NULL,size INTEGER NOT NULL,state TEXT NOT NULL,blob_hash TEXT NOT NULL,PRIMARY KEY(account,id),FOREIGN KEY(account,message_id) REFERENCES messages(account,id));
CREATE TABLE drafts(account TEXT NOT NULL,conversation_id TEXT NOT NULL,body TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(account,conversation_id),FOREIGN KEY(account,conversation_id) REFERENCES conversations(account,id));
CREATE TABLE operations(account TEXT NOT NULL,request_id TEXT NOT NULL,fingerprint TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(account,request_id),FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE views(account TEXT PRIMARY KEY,revision INTEGER NOT NULL,json TEXT NOT NULL,FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE calendar_sources(account TEXT NOT NULL,calendar_id TEXT NOT NULL,event_id TEXT NOT NULL,json TEXT NOT NULL,PRIMARY KEY(account,calendar_id,event_id),FOREIGN KEY(account) REFERENCES accounts(id));
PRAGMA user_version=1;
COMMIT;
